'''
# File: cm/karras_diffusion.py
from piq import LPIPS
import torch as th
import torch.nn.functional as F
import numpy as np
from .nn import mean_flat, append_dims, append_zero

class KarrasDenoiser:
    def __init__(self, sigma_data=0.5, sigma_max=80.0, sigma_min=0.002, rho=7.0, 
                 weight_schedule='karras', distillation=False, loss_norm='lpips'):
        self.sigma_data = sigma_data
        self.sigma_max = sigma_max
        self.sigma_min = sigma_min
        self.rho = rho
        self.weight_schedule = weight_schedule
        self.distillation = distillation
        self.loss_norm = loss_norm
        if loss_norm == 'lpips':
            self.lpips_loss = LPIPS(replace_pooling=True, reduction='none')
        self.num_timesteps = 40

    def get_snr(self, sigma):
        return sigma ** -2

    def get_scalings(self, sigma):
        c_skip = self.sigma_data**2 / (sigma**2 + self.sigma_data**2)
        c_out = sigma * self.sigma_data / ((sigma**2 + self.sigma_data**2) ** 0.5)
        c_in = 1 / ((sigma**2 + self.sigma_data**2) ** 0.5)
        return c_skip, c_out, c_in

    def get_scalings_for_boundary_condition(self, sigma):
        # Variant used for distillation or boundary conditions
        c_skip = self.sigma_data**2 / ((sigma - self.sigma_min)**2 + self.sigma_data**2)
        c_out = (sigma - self.sigma_min) * self.sigma_data / ((sigma**2 + self.sigma_data**2) ** 0.5)
        c_in = 1 / ((sigma**2 + self.sigma_data**2) ** 0.5)
        return c_skip, c_out, c_in

    def training_losses(self, model, x_start, sigma, model_kwargs=None, noise=None):
        if model_kwargs is None:
            model_kwargs = {}
        if noise is None:
            noise = th.randn_like(x_start)
        dims = x_start.ndim
        x_t = x_start + noise * append_dims(sigma, dims)
        model_output, denoised = self.denoise(model, x_t, sigma, **model_kwargs)
        snr = self.get_snr(sigma)
        weights = append_dims(snr, dims)  # simple weighting based on SNR
        mse_loss = mean_flat(weights * (denoised - x_start) ** 2)
        return { 'loss': mse_loss, 'mse': mse_loss }

    def consistency_losses(self, model, x_start, num_scales, model_kwargs=None, 
                             target_model=None, teacher_model=None, teacher_diffusion=None, noise=None):
        if model_kwargs is None:
            model_kwargs = {}
        if noise is None:
            noise = th.randn_like(x_start)
        dims = x_start.ndim

        def denoise_fn(x, t):
            return self.denoise(model, x, t, **model_kwargs)[1]

        if target_model:
            @th.no_grad()
            def target_denoise_fn(x, t):
                return self.denoise(target_model, x, t, **model_kwargs)[1]
        else:
            raise NotImplementedError('Must have a target model')

        if teacher_model:
            @th.no_grad()
            def teacher_denoise_fn(x, t):
                return teacher_diffusion.denoise(teacher_model, x, t, **model_kwargs)[1]
        else:
            teacher_denoise_fn = None

        indices = th.randint(0, num_scales - 1, (x_start.shape[0],), device=x_start.device)
        t = self.sigma_max ** (1 / self.rho) + indices / (num_scales - 1) * (
            self.sigma_min ** (1 / self.rho) - self.sigma_max ** (1 / self.rho)
        )
        t = t ** self.rho

        x_t = x_start + noise * append_dims(t, dims)
        denoised = denoise_fn(x_t, t)
        target = target_denoise_fn(x_t, t)

        if self.loss_norm == 'lpips':
            # Optionally resize when working on low-resolution images
            if x_start.shape[-1] < 256:
                denoised = F.interpolate(denoised, size=224, mode='bilinear')
                target = F.interpolate(target, size=224, mode='bilinear')
            loss = self.lpips_loss((denoised + 1) / 2.0, (target + 1) / 2.0)
            loss = mean_flat(loss)
        elif self.loss_norm == 'l2':
            loss = mean_flat((denoised - target) ** 2)
        else:
            raise ValueError(f'Unknown loss norm {self.loss_norm}')

        return { 'loss': loss }

    def denoise(self, model, x_t, sigma, **model_kwargs):
        dims = x_t.ndim
        if not self.distillation:
            c_skip, c_out, c_in = self.get_scalings(sigma)
        else:
            c_skip, c_out, c_in = self.get_scalings_for_boundary_condition(sigma)
        rescaled_t = 1000 * 0.25 * th.log(sigma + 1e-44)
        model_output = model(c_in * x_t, rescaled_t, **model_kwargs)
        denoised = c_out * model_output + c_skip * x_t
        return model_output, denoised
