############################################
# Minimal JAX core: autodidax implementation  #
############################################

# The following code is a distilled excerpt from the repository documentation
# demonstrating the core method: implementing automatic differentiation by
# defining a set of primitive operations and building context‐sensitive interpreters
# (traces) that allow us to transform a pure Python function into a staged representation
# (e.g. by propagating dual numbers for forward‐mode AD, or by tracing to a jaxpr).

from typing import NamedTuple, Any
from contextlib import contextmanager
import numpy as np
import jax.numpy as jnp

# --------------------------------------------------------------------
# 1. Define the set of primitives
# --------------------------------------------------------------------

class Primitive(NamedTuple):
    name: str

# Define some primitive operations
add_p = Primitive('add')
mul_p = Primitive('mul')
neg_p = Primitive('neg')
sin_p = Primitive('sin')
cos_p = Primitive('cos')

# User facing wrappers

def add(x, y):
    # Dispatches to the current interpreter
    from __main__ import current_interpreter
    return current_interpreter.process_primitive(add_p, (x, y), {})[0]

def mul(x, y):
    from __main__ import current_interpreter
    return current_interpreter.process_primitive(mul_p, (x, y), {})[0]

def neg(x):
    from __main__ import current_interpreter
    return current_interpreter.process_primitive(neg_p, (x,), {})[0]

def sin(x):
    from __main__ import current_interpreter
    return current_interpreter.process_primitive(sin_p, (x,), {})[0]

def cos(x):
    from __main__ import current_interpreter
    return current_interpreter.process_primitive(cos_p, (x,), {})[0]

# --------------------------------------------------------------------
# 2. Define the interpreter framework (trace and tracer)
# --------------------------------------------------------------------

class Trace:
    def __init__(self) -> None:
        pass
    def process_primitive(self, prim, args, params):
        raise NotImplementedError
    def lift(self, val):
        raise NotImplementedError

class Tracer:
    def __init__(self, trace: Trace, val: Any):
        self.trace = trace
        self.val = val
    def __add__(self, other):
        return add(self, other)
    def __mul__(self, other):
        return mul(self, other)
    def __neg__(self):
        return neg(self)
    # Additional operator overloads omitted for brevity

# Global context for the current interpreter (default is evaluation)

class EvalTrace(Trace):
    def process_primitive(self, prim, args, params):
        # In evaluation, the primitive is executed directly on the values
        # If an argument is a tracer, we extract its value.
        plain_args = [a.val if isinstance(a, Tracer) else a for a in args]
        if prim == add_p:
            return [plain_args[0] + plain_args[1]]
        elif prim == mul_p:
            return [plain_args[0] * plain_args[1]]
        elif prim == neg_p:
            return [ - plain_args[0] ]
        elif prim == sin_p:
            return [jnp.sin(plain_args[0])]
        elif prim == cos_p:
            return [jnp.cos(plain_args[0])]
        else:
            raise ValueError(f"Unknown primitive: {prim}")
    def lift(self, val):
        return Tracer(self, val)

current_interpreter = EvalTrace()

# --------------------------------------------------------------------
# 3. Implementation of forward-mode AD using dual numbers.
# --------------------------------------------------------------------

# We define a tracer that carries a dual number (primal, tangent)

class DualTracer(Tracer):
    def __init__(self, trace: Trace, primal: float, tangent: float):
        super().__init__(trace, (primal, tangent))
        self.primal = primal
        self.tangent = tangent

class JVPTrace(Trace):
    def process_primitive(self, prim, args, params):
        # Ensure arguments are DualTracers
        duals = [a if isinstance(a, DualTracer) else self.lift(a) for a in args]
        if prim == add_p:
            # (xp, xt) + (yp, yt) = (xp+yp, xt+yt)
            p_out = duals[0].primal + duals[1].primal
            t_out = duals[0].tangent + duals[1].tangent
        elif prim == mul_p:
            # (xp, xt) * (yp, yt) = (xp*yp, xp*yt + xt*yp)
            p_out = duals[0].primal * duals[1].primal
            t_out = duals[0].primal * duals[1].tangent + duals[0].tangent * duals[1].primal
        elif prim == neg_p:
            p_out = -duals[0].primal
            t_out = -duals[0].tangent
        elif prim == sin_p:
            p_out = jnp.sin(duals[0].primal)
            t_out = jnp.cos(duals[0].primal) * duals[0].tangent
        elif prim == cos_p:
            p_out = jnp.cos(duals[0].primal)
            t_out = -jnp.sin(duals[0].primal) * duals[0].tangent
        else:
            raise ValueError(f"Unknown primitive in JVP: {prim}")
        return [DualTracer(self, p_out, t_out)]
    def lift(self, val):
        # Lift a constant to a dual number with zero tangent
        return DualTracer(self, val, 0.0)

# Utility: run a function under a given trace

@contextmanager
def use_interpreter(trace: Trace):
    global current_interpreter
    old = current_interpreter
    current_interpreter = trace
    try:
        yield
    finally:
        current_interpreter = old


# The jvp function: given a function f and an input x with tangent x_dot,
# compute f(x) and the product of the Jacobian with x_dot.

def jvp(f, x, x_dot):
    jvp_trace = JVPTrace()
    with use_interpreter(jvp_trace):
        x_dual = jvp_trace.lift(x)
        # Override x_dual with provided tangent
        x_dual.tangent = x_dot
        y_dual = f(x_dual)
    return y_dual.primal, y_dual.tangent

# Example function defined using the primitives

def foo(x):
    # foo(x) = x * (x + 3)
    return mul(x, add(x, 3.0))

# Compute the first and second derivatives

def derivative(f, x):
    _, tangent = jvp(f, x, 1.0)
    return tangent


def nth_order_derivative(n, f, x):
    if n == 0:
        return f(x)
    else:
        return derivative(lambda x: nth_order_derivative(n-1, f, x), x)

# Test the implementation

print('foo(2.0) =', foo(2.0))
print('First derivative of foo at 2.0:', derivative(foo, 2.0))
print('Second derivative of foo at 2.0:', nth_order_derivative(2, foo, 2.0))
print('Higher derivatives (should be 0):', nth_order_derivative(3, foo, 2.0))

